Here is the commit message:
src: udp_flood fix PPS calc and use DEFAULT_COUNT

Fixing bugs introduced in commit 200b8079339c ("flood: move all
options inside a struct").

First fix PPS calculations, which didn't want to provide PPS if
test time was below 1 sec, very strange.  It seemed like a
unintentional changed introduced in the commit.

Second use the DEFAULT_COUNT as the default count value at init.

Fixes: 200b8079339c ("flood: move all options inside a struct")
Signed-off-by: Jesper Dangaard Brouer <brouer@redhat.com>

Here is the root cause:
The bug was caused by an unintended change in the PPS calculation logic introduced in a previous commit, which incorrectly prevented the calculation of packets per second (PPS) when the test time was less than one second. Additionally, the hardcoded default count value of `1000000` was not flexible or configurable, potentially leading to inappropriate test configurations.

Here is the patch:

 static void time_function(int sockfd, struct flood_params *p,
 	int (*func)(int sockfd, struct flood_params *p))
 {
 	uint64_t tsc_begin,  tsc_end,  tsc_interval;
 	uint64_t time_begin, time_end, time_interval;
 	int cnt_send;
-	double pps=0, ns_per_pkt=0, timesec=0;
+	double pps, ns_per_pkt=0, timesec=0;
 	uint64_t tsc_cycles = 0;

 	time_begin = gettime();
 	tsc_begin  = rdtsc();
 	cnt_send = func(sockfd, p);
 	//cnt_send = flood_with_sendmsg(sockfd, dest_addr, count, msg_sz);
 	//cnt_send = flood_with_sendto(sockfd, dest_addr, count, msg_sz);
 	tsc_end  = rdtsc();
 	time_end = gettime();
 	tsc_interval  = tsc_end  - tsc_begin;
 	time_interval = time_end - time_begin;

 	if (cnt_send < 0) {
 		fprintf(stderr, "ERROR: failed to send packets\n");
 		close(sockfd);
 		exit(EXIT_FAIL_SEND);
 	}

 	/* Stats */
-	if (time_interval / NANOSEC_PER_SEC)
-		pps = cnt_send / ((double)time_interval / NANOSEC_PER_SEC);
+	pps = cnt_send / ((double)time_interval / NANOSEC_PER_SEC);
 	if (cnt_send) {
 		tsc_cycles = tsc_interval / cnt_send;
 		ns_per_pkt = ((double)time_interval / cnt_send);
 	}
 	timesec    = ((double)time_interval / NANOSEC_PER_SEC);
 	print_result(tsc_cycles, ns_per_pkt, pps, timesec,
 		     cnt_send, tsc_interval);
 }

 static void init_params(struct flood_params *params)
 {
 	memset(params, 0, sizeof(struct flood_params));
-	params->count  = 1000000;
+	params->count  = DEFAULT_COUNT;
 	params->batch = 32;
 	params->msg_sz = 18; /* 18 +14(eth)+8(UDP)+20(IP)+4(Eth-CRC) = 64 bytes */
 	params->pmtu = -1;
 }



